LESSONS["1A"].grammar.points.push({"label": "نقطه ۵", "title": "Common adverbs & common errors", "html": "<h3>Most common manner adverbs</h3>\n<p>پرکاربردترین قیدهای حالت که با <b>-ly</b> ساخته می‌شوند:</p>\n<div class=\"ex\">quickly · easily · differently · automatically · slowly · properly · badly · strongly · carefully</div>\n<h3>Common errors</h3>\n<p>برای توصیف اینکه یک کار <b>چگونه</b> انجام می‌شود، هرگز از صفت استفاده نکنید.</p>\n<div class=\"err\">✗ Children learn languages <b>easy</b>.<span class=\"en\">✓ Children learn languages easily.</span></div>\n<p>بعد از <b>be, feel, get</b> و افعال ربطی مشابه، صفت می‌آید.</p>\n<div class=\"ex\">I feel <span class=\"hl\">safe</span> with her. · He gets <span class=\"hl\">reckless</span> sometimes.</div>\n<div class=\"note\">استثنا: <b>I feel strongly about it.</b> — اینجا strongly قید است.</div>", "qs": [{"q": "Children learn languages _____.", "o": ["easy", "easily"], "a": 1, "ex": "چگونه یاد گرفتن → قید."}, {"q": "I feel _____ with her.", "o": ["safe", "safely"], "a": 0, "ex": "بعد از feel صفت می‌آید."}], "qs2": [{"q": "He gets _____ in traffic.", "o": ["angry", "angrily"], "a": 0, "ex": "get + صفت."}, {"q": "She speaks _____ in meetings.", "o": ["confident", "confidently"], "a": 1, "ex": "چگونه صحبت می‌کند → قید."}]});
Object.assign(LESSONS["1A"],{"quiz": [{"q": "When I walk down the street, …", "a": "I walk very fast and use the time to make phone calls.", "b": "I enjoy the walk and look at the things and people around me.", "fa": "وقتی در خیابان راه می‌روم…\nالف) خیلی تند راه می‌روم و از این زمان برای تماس تلفنی استفاده می‌کنم.\nب) از قدم زدن لذت می‌برم و به چیزها و آدم‌های اطرافم نگاه می‌کنم."}, {"q": "When I go out to lunch with friends, …", "a": "I eat quickly so that I can get back to my work.", "b": "I eat slowly, and I enjoy the food and conversation.", "fa": "وقتی با دوستان برای ناهار بیرون می‌روم…\nالف) سریع غذا می‌خورم تا زود به کارم برگردم.\nب) آهسته غذا می‌خورم و از غذا و گفتگو لذت می‌برم."}, {"q": "When there's a family event, …", "a": "I often have to miss it because I have too much to do.", "b": "I try to plan my time well so that I can attend the event.", "fa": "وقتی مراسم خانوادگی هست…\nالف) اغلب مجبورم شرکت نکنم چون کار زیادی دارم.\nب) سعی می‌کنم وقتم را خوب برنامه‌ریزی کنم تا بتوانم در مراسم حاضر شوم."}, {"q": "If traffic is heavy and some people are driving a bit recklessly, …", "a": "I honk my horn a lot. I get mad easily in bad traffic.", "b": "I automatically slow down and try to drive carefully.", "fa": "اگر ترافیک سنگین باشد و بعضی‌ها کمی بی‌پروا رانندگی کنند…\nالف) زیاد بوق می‌زنم. در ترافیک بد زود عصبانی می‌شوم.\nب) خودکار سرعتم را کم می‌کنم و سعی می‌کنم با احتیاط رانندگی کنم."}, {"q": "If I'm waiting at the airport and find out that my flight is delayed, …", "a": "I get impatient and complain to the people behind the counter.", "b": "I wait patiently. I read something or make a few phone calls.", "fa": "اگر در فرودگاه منتظرم و بفهمم پروازم تأخیر دارد…\nالف) بی‌حوصله می‌شوم و به کارکنان باجه شکایت می‌کنم.\nب) صبورانه منتظر می‌مانم. چیزی می‌خوانم یا چند تماس می‌گیرم."}, {"q": "If I'm in a hurry and think people are talking too slowly, …", "a": "I sometimes interrupt them to finish their sentences.", "b": "I listen quietly and wait for them to finish before I talk.", "fa": "اگر عجله دارم و فکر می‌کنم مردم خیلی آهسته حرف می‌زنند…\nالف) گاهی وسط حرفشان می‌پرم و جمله‌شان را تمام می‌کنم.\nب) آرام گوش می‌دهم و صبر می‌کنم حرفشان تمام شود."}, {"q": "If I play a game or sport with friends, …", "a": "I take the game seriously, and I feel very bad if I lose.", "b": "I think it's better to win than lose, but I don't feel strongly about it.", "fa": "اگر با دوستان بازی یا ورزش می‌کنم…\nالف) بازی را جدی می‌گیرم و اگر ببازم خیلی بد می‌شوم.\nب) فکر می‌کنم بردن بهتر از باختن است، اما خیلی روی آن حساس نیستم."}, {"q": "If I get an assignment with a very tight deadline, …", "a": "I get very stressed – I hate it when I don't have time to do a job properly.", "b": "I work hard to do the best I can in the time I have.", "fa": "اگر تکلیفی با مهلت خیلی کوتاه بگیرم…\nالف) خیلی استرس می‌گیرم؛ از اینکه وقت کافی برای انجام درست کار نداشته باشم بدم می‌آید.\nب) سخت تلاش می‌کنم تا در زمانی که دارم بهترین کارم را بکنم."}], "quizResult": {"A": {"en": "It's time to slow down and enjoy life more. Try to plan your time differently. Make more time for family, friends, and fun.", "fa": "وقتش است آرام‌تر شوید و بیشتر از زندگی لذت ببرید. سعی کنید زمانتان را جور دیگری برنامه‌ریزی کنید. برای خانواده، دوستان و تفریح وقت بیشتری بگذارید."}, "B": {"en": "You're balancing work and play nicely. Just keep the balance right.", "fa": "شما تعادل خوبی بین کار و تفریح دارید. فقط این تعادل را حفظ کنید."}}, "circle": [{"q": "I have a lot of _____ deadlines.", "o": ["tight", "tightly"], "a": 0, "ex": "قبل از اسم (deadlines) صفت می‌آید."}, {"q": "I plan my time _____.", "o": ["good", "well"], "a": 1, "ex": "قیدِ good کلمهٔ well است."}, {"q": "I often eat lunch _____.", "o": ["quick", "quickly"], "a": 1, "ex": "چگونگی انجام کار (eat) با قید بیان می‌شود."}, {"q": "I feel _____ about my opinions.", "o": ["strong", "strongly"], "a": 1, "ex": "feel strongly about = عقیدهٔ قوی داشتن؛ اینجا قید می‌آید."}, {"q": "I get _____ in long lines.", "o": ["impatient", "impatiently"], "a": 0, "ex": "بعد از get (به معنی «شدن») صفت می‌آید."}, {"q": "I work _____ to get good grades.", "o": ["hard", "hardly"], "a": 0, "ex": "hard هم صفت و هم قید است؛ hardly یعنی «تقریباً هرگز»."}], "exA": [{"q": "Young people don't speak _____.", "o": ["clear", "clearly"], "a": 1, "ex": "بعد از فعل speak قید می‌آید."}, {"q": "Their slang sounds _____.", "o": ["terrible", "terribly"], "a": 0, "ex": "sound فعل ربطی است؛ بعد از آن صفت می‌آید."}, {"q": "They don't always communicate _____.", "o": ["good", "well"], "a": 1, "ex": "قیدِ good کلمهٔ well است."}, {"q": "People aren't very _____ when they have to wait in long lines.", "o": ["patient", "patiently"], "a": 0, "ex": "بعد از be صفت می‌آید."}, {"q": "They don't speak to the clerks very _____, either.", "o": ["polite", "politely"], "a": 1, "ex": "چگونه صحبت کردن → قید."}, {"q": "Sometimes families argue because parents and children see things _____.", "o": ["different", "differently"], "a": 1, "ex": "چگونه دیدن → قید."}, {"q": "A lot of people _____ answer their cell phones when they ring.", "o": ["automatic", "automatically"], "a": 1, "ex": "توصیف فعل answer → قید."}, {"q": "I think that's just _____.", "o": ["rude", "rudely"], "a": 0, "ex": "بعد از be (that's) صفت می‌آید."}, {"q": "People don't feel _____ on the roads.", "o": ["safe", "safely"], "a": 0, "ex": "بعد از feel صفت می‌آید."}, {"q": "…because so many people are driving _____.", "o": ["reckless", "recklessly"], "a": 1, "ex": "توصیف فعل driving → قید."}, {"q": "Driving can be _____.", "o": ["dangerous", "dangerously"], "a": 0, "ex": "بعد از be صفت می‌آید."}, {"q": "A lot of people try _____ to do their job…", "o": ["hard", "hardly"], "a": 0, "ex": "try hard = تلاش زیاد کردن؛ hardly معنی دیگری دارد."}, {"q": "…to do their job _____, and they get stressed.", "o": ["thorough", "thoroughly"], "a": 1, "ex": "چگونه انجام دادن کار → قید."}], "sessions": [{"id": "cb1", "stage": "Coursebook", "icon": "❓", "title": "Do you need to slow down?", "fa": "آزمون: آیا باید آرام‌تر شوید؟", "parts": [{"t": "quiz"}]}, {"id": "cb2", "stage": "Coursebook", "icon": "⭕", "title": "Circle the correct words", "fa": "کلمهٔ درست را انتخاب کنید", "parts": [{"t": "circle"}]}, {"id": "cb3", "stage": "Coursebook", "icon": "📝", "title": "Adjectives vs. manner adverbs", "fa": "صفت و قید حالت", "parts": [{"t": "gpoints", "pts": [0, 1, 2, 3]}]}, {"id": "cb4", "stage": "Coursebook", "icon": "⚠️", "title": "Common errors & Exercise A", "fa": "اشتباهات رایج و تمرین A", "parts": [{"t": "gpoints", "pts": [4]}, {"t": "exA"}]}, {"id": "ex1", "stage": "Extra", "icon": "📚", "title": "Vocabulary 1", "fa": "لغات ۱", "parts": [{"t": "vocab", "from": 0, "to": 10}, {"t": "matching", "sets": [1, 2]}]}, {"id": "ex2", "stage": "Extra", "icon": "📚", "title": "Vocabulary 2", "fa": "لغات ۲", "parts": [{"t": "vocab", "from": 10, "to": 20}, {"t": "matching", "sets": [3, 4]}]}, {"id": "ex3", "stage": "Extra", "icon": "🧩", "title": "Gap-fill", "fa": "جای خالی", "parts": [{"t": "gap"}]}, {"id": "ex4", "stage": "Extra", "icon": "✅", "title": "Grammar test", "fa": "آزمون گرامر", "parts": [{"t": "test"}]}, {"id": "ex5", "stage": "Extra", "icon": "💬", "title": "Grammar passages", "fa": "متن‌های گرامر", "parts": [{"t": "passages"}]}, {"id": "ex6", "stage": "Extra", "icon": "📖", "title": "Reading 1", "fa": "خواندن ۱", "parts": [{"t": "reading", "text": 0}]}, {"id": "ex7", "stage": "Extra", "icon": "📖", "title": "Reading 2", "fa": "خواندن ۲", "parts": [{"t": "reading", "text": 1}]}, {"id": "ex8", "stage": "Extra", "icon": "✍️", "title": "Writing", "fa": "نوشتن", "parts": [{"t": "writing"}]}]});

