LESSONS["1B"].vocab=[["level-headed", "word", "باذکاوت، آروم و خونسرد در شرایط سخت", "During high-pressure meetings, our manager always remains level-headed."], ["thin-skinned", "word", "زودرنج و حساس به انتقاد", "It is quite difficult to give constructive feedback to someone who is thin-skinned."], ["have a heart of gold", "idiom", "قلب فوق‌العاده مهربانی داشتن", "Although he looks stern on the outside, our neighbor has a heart of gold."], ["speak one's mind", "chunk", "رک، صریح و بدون ترس ابراز نظر کردن", "She is never afraid to speak her mind during team planning sessions."], ["set in one's ways", "idiom", "غیرقابل انعطاف و پایبند به عادات قدیمی", "My grandfather is firmly set in his ways and refuses to use modern smartphones."], ["keep to oneself", "chunk", "گوشه‌گیر بودن و تمایل به حریم شخصی", "He is a polite colleague, but after work hours he prefers to keep to himself."], ["quick-witted", "word", "تیزهوش و حاضرجواب", "Her quick-witted responses made the panel discussion both engaging and informative."], ["stand up for someone", "chunk", "از کسی دفاع و حمایت کردن", "A true friend will always stand up for you when others make unfair assumptions."], ["two-faced", "word", "دوپیکر، منافق و دو‌رو", "Working with a person who is two-faced destroys trust within an office team."], ["light-hearted", "word", "شاد، بی‌خیال و فارغ از جدی بودن زیاد", "We enjoyed a light-hearted conversation over coffee after finishing the presentation."], ["down-to-earth", "word", "خاکی، خاکی‌منش و واقع‌بین", "He is very down-to-earth, so he always gives practical advice when I have problems."], ["count on someone", "chunk", "روی کسی حساب کردن / اعتماد کامل داشتن", "She is totally reliable, so you can always count on her during a crisis."], ["a sense of humor", "collocation", "حس شوخ‌طبعی", "Our teacher has a great sense of humor, which makes her classes lively and fun."], ["laid-back", "word", "بی‌خیال، راحت و آسوده‌خاطر", "My manager is pretty laid-back, so he does not panic when minor issues arise."], ["wear one's heart on one's sleeve", "idiom", "احساسات خود را رو بازی کردن و بر ملا ساختن", "You always know how he feels because he wears his heart on his sleeve."], ["a workaholic", "word", "معتاد به کار / پرکار خستگی‌ناپذیر", "She is a bit of a workaholic and finds it extremely difficult to relax on weekends."], ["open-minded", "word", "پذیرا، روشن‌فکر و فاقد تعصب", "Having an open-minded leader helps the department adapt to changes quickly."], ["narrow-minded", "word", "تنگ‌نظر و متعصب", "It is challenging to discuss new ideas with a person who is narrow-minded."], ["easygoing", "word", "خوش‌برخورد، آسان‌گیر و سازگار", "He is an easygoing person who gets along well with almost everyone."], ["self-centered", "word", "خودخواه و خودمحور", "People who are self-centered rarely show genuine concern for the feelings of others."]];
LESSONS["1B"].texts=[{"title": "Text 1: Personality Assessments and Human Growth", "topic": "Personality Assessments and Human Growth", "text": "Personality testing is a big industry in modern corporate business. Many companies test job candidates during the hiring process today. These written tests help managers understand candidate behaviors and work habits. Job seekers answer many detailed questions about their daily routines. The test results describe how people perform inside work teams. Employers want to build strong and cooperative office groups. Understanding personality helps colleagues communicate with greater ease and clarity. Personality tests are now common tools across major global corporations.\n\nThe Myers-Briggs test is the most famous personality assessment tool. It divides human beings into sixteen distinct psychological categories. The test measures how individuals receive and process new information. It also examines how people make important decisions under pressure. Some people are labeled as quiet and thoughtful introverts. Other individuals are categorized as outgoing and expressive extraverts. People often share their test results on professional social networks.\n\nHowever, many prominent psychologists question these simple character categories. They argue that human nature is far too complex for simple labels. A person can behave differently in different social environments. Human beings do not fit neatly into rigid personality boxes. Individual test results can change from month to month unexpectedly. Therefore, these popular tests are not always completely reliable. Critics advise managers not to rely heavily on simple test scores.\n\nModern brain science proves that adult human character can change. Neuroscientists call this important biological process neuroplasticity. The human brain forms new neural connections throughout adult life. Learning new skills alters how your physical brain operates daily. Life experiences continuously reshape human behavioral and emotional patterns. Adults are not stuck with their childhood personality traits forever. The adult brain remains flexible and open to new learning.\n\nLong-term research studies prove that character matures over time. Studies show that older adults gradually become more conscientious workers. People usually become much more agreeable as they grow older. Emotional stability also improves significantly during mature adult years. Work obligations help individuals build strong daily self-discipline. Family responsibilities encourage adults to become more patient listeners. Aging brings valuable wisdom and greater emotional self-control.\n\nIndividuals can actively practice and develop new behavioral habits. A disorganized person can learn and apply better daily systems. An impatient worker can practice calm and attentive listening daily. Small daily actions lead to significant character improvements over time. Conscious daily effort helps people overcome negative personal habits. Personal growth requires clear dedication and sustained mental focus. Anyone can choose to cultivate positive new personality traits.\n\nOrganizations benefit greatly when employees develop strong self-awareness. Workers who understand themselves interact with colleagues more effectively. They manage workplace conflicts with greater calm and patience. Teams become much more productive and supportive as a result. Respecting diverse personality styles improves overall office team morale. Positive workplace communication creates a healthy working environment. Companies succeed when they value diverse employee character strengths.\n\nIn conclusion, human personality is not a fixed or permanent state. Our character continues to evolve throughout our entire adult life. Scientific research proves that adults can actively shape their habits. Self-awareness allows us to make positive personal changes every day. With time and dedication, anyone can achieve meaningful personal growth.", "glossary": {}, "hl": [], "gist": {"q": "What is the main idea of this article?", "o": ["Why companies should fire introverted employees.", "How personality testing works and why adult character can change through neuroplasticity.", "How to cheat on the Myers-Briggs personality assessment.", "Why childhood habits determine your salary forever."], "a": 1}, "detailed": [{"q": "Why do some psychologists criticize popular personality tests like the Myers-Briggs test?", "o": ["Because the tests cost too much money for small companies.", "Because human nature is complex and test results can change over time.", "Because introverts refuse to take written tests online.", "Because the test was created over three hundred years ago."], "a": 1, "ex": "Paragraph 3 explains that critics question personality tests because human nature is complex, people behave differently in different environments, and test results can change."}, {"q": "What is neuroplasticity according to the fourth paragraph?", "o": ["A mental illness caused by working too hard.", "The brain's ability to form new neural connections and change during adult life.", "A personality test used to measure worker productivity.", "A physical exercise designed to improve sleep quality."], "a": 1, "ex": "Paragraph 4 defines neuroplasticity as the biological process where the adult brain forms new neural connections and reshapes behavior patterns."}, {"q": "How does human personality typically mature as adults age?", "o": ["Adults become more disorganized and impatient.", "People become more conscientious, agreeable, and emotionally stable over time.", "Adults lose their ability to learn new behavioral habits.", "Individuals become very selfish and arrogant."], "a": 1}]}, {"title": "Text 2: Introversion, Extraversion, and Modern Leadership", "topic": "Introversion, Extraversion, and Modern Leadership", "text": "Western business culture has favored outgoing and extraverted personalities for decades. Charismatic leaders often receive quick promotions in corporate environments. Open-plan offices were designed to encourage active group conversations. Team brainstorming sessions reward workers who speak up quickly. Aggressive networking events also benefit outgoing and expressive professionals. Extraverts feel energized when surrounded by large crowds of people. They express their ideas with high energy and passion. Consequently, extraverted workers often dominate office meetings and discussions. Many business schools traditionally trained students to act extraverted.\n\nConversely, introverted employees are frequently misunderstood in modern offices. Introverted individuals are usually quiet, reflective, and pretty reserved. Managers sometimes mischaracterize quiet workers as unfriendly or lacking ambition. However, shyness and introversion are entirely different character traits. Shy people feel anxious during normal social interactions with strangers. Introverts simply prefer quiet environments to process new thoughts. They recharge their personal energy by spending time alone. Quiet reflection allows them to analyze problems deeply before speaking.\n\nRecent organizational psychology research reveals surprising facts about introverted leaders. Introverted managers are incredibly effective at leading proactive teams. Extraverted leaders sometimes interrupt employees and push their own ideas. In contrast, introverted leaders listen carefully to suggestions from staff. They absorb feedback thoroughly before making major business decisions. They allow talented employees to run with creative new initiatives. This quiet support fosters strong team autonomy and trust. Employees feel empowered when their leaders listen attentively to them.\n\nModern workplaces require deep focus and complex analytical skills daily. Introverted professionals excel at tasks that demand sustained mental focus. They write detailed reports and analyze financial numbers very carefully. They do not get distracted easily by noisy office environments. Their methodical approach reduces costly administrative errors in business projects. They complete challenging tasks without needing constant public praise. Their quiet dedication ensures high operational quality across departments. They take great pride in delivering accurate and reliable work.\n\nForcing introverts to act like extraverts is completely counterproductive. Mandatory social events can cause severe exhaustion for quiet workers. Constant group meetings prevent introverts from doing deep work. Companies waste valuable talent when they ignore quiet professionals. Smart managers design quiet spaces for focused individual work. They offer different ways for staff to share their ideas. Written feedback allows introverts to contribute without high stress. Inclusive managers help every employee thrive in their own way.\n\nPsychologists measure personality using the Big Five personality framework. This model evaluates extraversion alongside four other key traits. These traits include conscientiousness, agreeableness, openness, and emotional stability. High conscientiousness predicts strong workplace performance and personal reliability. High agreeableness fosters warm cooperation among team members daily. Openness to experience encourages creative problem solving in organizations. Successful teams require a healthy balance of different personality traits.\n\nResilient organizations need both extraverted and introverted professionals to thrive. Outgoing extraverts excel at public presentation and client sales negotiations. They build exciting networks and attract new business opportunities quickly. Down-to-earth introverts ensure operational stability and careful quality control. Combining these different strengths creates a highly balanced workforce. Mutual respect between different personality types improves overall productivity. Every worker brings unique value to the shared corporate mission. Diversity of character drives innovation across modern global companies.\n\nIn conclusion, introversion is a powerful asset in modern business. Quiet leaders and focused workers bring essential strengths to teams. Companies must value both quiet focus and charismatic energy. Embracing diverse personality types leads to sustainable long-term success. Understanding personality differences builds stronger and happier workplaces.", "glossary": {}, "hl": [], "gist": {"q": "What is the primary focus of this article?", "o": ["Why companies should eliminate all extraverted managers.", "The value of both introverted and extraverted traits in leadership and modern business.", "How to organize large corporate parties.", "The history of open-plan office furniture."], "a": 1}, "detailed": [{"q": "What is the fundamental difference between shyness and introversion described in paragraph 2?", "o": ["Shy people hate music, while introverts love classical music.", "Shyness involves anxiety in social situations, while introversion is simply a preference for quiet environments to process thoughts.", "Introverts are always disorganized, while shy people are extremely reliable.", "Shyness only affects children, while introversion only affects adults."], "a": 1, "ex": "Paragraph 2 clarifies that shy people feel anxious in social interactions, whereas introverts simply prefer quiet environments to recharge and process thoughts."}, {"q": "Why are introverted leaders particularly effective when managing proactive teams?", "o": ["Because they yell at workers who make mistakes.", "Because they listen carefully to feedback and allow talented staff to run with new ideas.", "Because they force everyone to work late every evening.", "Because they refuse to attend team meetings."], "a": 1, "ex": "Paragraph 3 explains that introverted leaders listen carefully to suggestions and allow proactive employees to execute creative initiatives without interference."}, {"q": "How can smart managers help introverted employees contribute effectively in the workplace?", "o": ["By forcing them to give public speeches every day.", "By providing quiet workspaces and offering options like written feedback.", "By ignoring their work completely.", "By banning smartphones from the building."], "a": 1}]}];
LESSONS["1B"].writing={"prompts": [{"title": "Prompt 1", "text": "Write a short personal profile (100–150 words) describing a colleague, friend, or relative whom you deeply respect. Detail their major character strengths and minor behavioral flaws using at least four degree adverbs (incredibly, extremely, fairly, pretty, totally), two prefixed adjectives (impatient, inconsiderate, unreliable, disorganized), and two character expressions from Section 1 (level-headed, heart of gold, speak one's mind, stand up for).", "sample": "I would like to describe my senior colleague, Farhad, whom I truly admire. He is an incredibly level-headed project lead who manages complex engineering assignments with impressive calm. He is extremely generous with his time and genuinely has a heart of gold, as he is always ready to assist junior staff.\nHe is completely honest in his communications and never hesitates to speak his mind during strategy meetings. On occasion, he can be fairly disorganized with his administrative paperwork, and he gets a bit impatient when software tools operate slowly. However, he is never inconsiderate at all, and his overall leadership is absolutely wonderful. He is a totally reliable professional whom everyone on our team can depend on."}, {"title": "Prompt 2", "text": "Write a paragraph (100–150 words) reflecting on your own personality traits. Discuss one character strength you are proud of and one habit or trait you would like to improve. You must use at least four degree adverbs (extremely, incredibly, pretty, fairly, absolutely), two prefixed adjectives (impatient, disorganized, inconsiderate, impolite), and correct adjective-adverb structures."}]};
LESSONS["1B"].pretest=[{"q": "Winning is very important to you.", "o": ["competitive", "easygoing", "reliable", "disorganized"], "a": 0, "ex": ""}, {"q": "You're relaxed about life.", "o": ["easygoing", "competitive", "arrogant", "dishonest"], "a": 0, "ex": ""}, {"q": "You handle small problems well.", "o": ["easygoing", "unreliable", "selfish", "inconsiderate"], "a": 0, "ex": ""}, {"q": "You never cheat or steal.", "o": ["honest", "dishonest", "arrogant", "disorganized"], "a": 0, "ex": ""}, {"q": "People can always count on you.", "o": ["reliable", "unreliable", "disorganized", "unfriendly"], "a": 0, "ex": ""}, {"q": "You're not well organized.", "o": ["disorganized", "reliable", "generous", "honest"], "a": 0, "ex": ""}, {"q": "You don't get along with people.", "o": ["unfriendly", "generous", "easygoing", "reliable"], "a": 0, "ex": ""}, {"q": "You can do a lot of things well.", "o": ["talented", "dishonest", "disorganized", "impatient"], "a": 0, "ex": ""}, {"q": "You like to have fun with people.", "o": ["have a great sense of humor", "arrogant", "unfriendly", "inconsiderate"], "a": 0, "ex": ""}, {"q": "You think you're the best.", "o": ["arrogant", "humble", "generous", "down-to-earth"], "a": 0, "ex": ""}, {"q": "You're not relaxed around people.", "o": ["shy", "outgoing", "generous", "competitive"], "a": 0, "ex": ""}, {"q": "You give a lot of your time or money.", "o": ["generous", "selfish", "arrogant", "dishonest"], "a": 0, "ex": ""}];
LESSONS["1B"].grammar.bookExA=[{"q": "My uncle is _____ laid-back — nothing ever bothers him.", "o": ["totally", "not"], "a": 0, "ex": "totally = کاملاً."}, {"q": "She's _____ generous — always buying little gifts for people.", "o": ["pretty", "not at all"], "a": 0, "ex": "pretty = تا حدی."}, {"q": "He was _____ honest with me about the mistake.", "o": ["very", "not very"], "a": 0, "ex": "very برای تأکید معمولی به کار می‌رود."}, {"q": "The view from the summit was _____ wonderful.", "o": ["absolutely", "fairly"], "a": 0, "ex": "wonderful صفت مطلق است؛ absolutely درست است."}, {"q": "He's not competitive _____; he doesn't even care who wins.", "o": ["at all", "completely"], "a": 0, "ex": "at all بعد از منفی می‌آید."}, {"q": "She gets _____ impatient in long lines.", "o": ["incredibly", "pretty much"], "a": 0, "ex": "incredibly قبل از صفت می‌آید."}, {"q": "My notes are _____ disorganized this week.", "o": ["fairly", "totally not"], "a": 0, "ex": "fairly = تا حدی."}, {"q": "He's _____ reliable — you can always count on him.", "o": ["completely", "fairly"], "a": 0, "ex": "completely = کاملاً."}, {"q": "She's an _____ talented painter.", "o": ["extremely", "extreme"], "a": 0, "ex": "قبل از صفت باید قید بیاید."}, {"q": "That comment was _____ inconsiderate.", "o": ["really", "real"], "a": 0, "ex": "قبل از صفت باید قید بیاید."}];
LESSONS["1B"].grammar.buildingVocab=[{"q": "Winning is very important to you.", "o": ["competitive", "easygoing", "reliable", "disorganized"], "a": 0, "ex": ""}, {"q": "You're relaxed about life.", "o": ["easygoing", "competitive", "arrogant", "dishonest"], "a": 0, "ex": ""}, {"q": "You handle small problems well.", "o": ["easygoing", "unreliable", "selfish", "inconsiderate"], "a": 0, "ex": ""}, {"q": "You never cheat or steal.", "o": ["honest", "dishonest", "arrogant", "disorganized"], "a": 0, "ex": ""}, {"q": "People can always count on you.", "o": ["reliable", "unreliable", "disorganized", "unfriendly"], "a": 0, "ex": ""}, {"q": "You're not well organized.", "o": ["disorganized", "reliable", "generous", "honest"], "a": 0, "ex": ""}, {"q": "You don't get along with people.", "o": ["unfriendly", "generous", "easygoing", "reliable"], "a": 0, "ex": ""}, {"q": "You can do a lot of things well.", "o": ["talented", "dishonest", "disorganized", "impatient"], "a": 0, "ex": ""}, {"q": "You like to have fun with people.", "o": ["have a great sense of humor", "arrogant", "unfriendly", "inconsiderate"], "a": 0, "ex": ""}, {"q": "You think you're the best.", "o": ["arrogant", "humble", "generous", "down-to-earth"], "a": 0, "ex": ""}, {"q": "You're not relaxed around people.", "o": ["shy", "outgoing", "generous", "competitive"], "a": 0, "ex": ""}, {"q": "You give a lot of your time or money.", "o": ["generous", "selfish", "arrogant", "dishonest"], "a": 0, "ex": ""}];
LESSONS["1B"].grammar.extraQuiz1=[{"q": "He's _____ generous with his time.", "o": ["extremely", "extreme"], "a": 0, "ex": ""}, {"q": "She's _____ easygoing about small mistakes.", "o": ["pretty", "absolutely"], "a": 0, "ex": ""}, {"q": "Her cooking is _____ amazing.", "o": ["absolutely", "very"], "a": 0, "ex": ""}, {"q": "He's not selfish _____.", "o": ["at all", "completely"], "a": 0, "ex": ""}, {"q": "They're _____ reliable business partners.", "o": ["totally", "fairly a bit"], "a": 0, "ex": ""}, {"q": "My brother is _____ laid-back about deadlines.", "o": ["fairly", "totally not"], "a": 0, "ex": ""}, {"q": "The opposite of \"friendly\" is _____.", "o": ["unfriendly", "disfriendly"], "a": 0, "ex": ""}, {"q": "The opposite of \"honest\" is _____.", "o": ["dishonest", "unhonest"], "a": 0, "ex": ""}, {"q": "She's _____ talented at the piano.", "o": ["incredibly", "incredible"], "a": 0, "ex": ""}, {"q": "He's a _____ cool guy, very down-to-earth.", "o": ["pretty", "pretty much a"], "a": 0, "ex": ""}];
LESSONS["1B"].grammar.extraQuiz2=[{"q": "The opposite of \"organized\" is _____.", "o": ["disorganized", "inorganized"], "a": 0, "ex": ""}, {"q": "The opposite of \"patient\" is _____.", "o": ["impatient", "unpatient"], "a": 0, "ex": ""}, {"q": "The opposite of \"reliable\" is _____.", "o": ["unreliable", "disreliable"], "a": 0, "ex": ""}, {"q": "She's not arrogant _____ — she's actually very humble.", "o": ["at all", "totally"], "a": 0, "ex": ""}, {"q": "He's _____ honest about his opinions.", "o": ["completely", "fairly not"], "a": 0, "ex": ""}, {"q": "Their new manager is _____ competitive.", "o": ["extremely", "extreme"], "a": 0, "ex": ""}, {"q": "She's _____ disorganized, but she always finishes on time.", "o": ["pretty", "absolutely"], "a": 0, "ex": ""}, {"q": "That was an _____ generous thing to do.", "o": ["incredibly", "incredible"], "a": 0, "ex": ""}, {"q": "He's _____ reliable — I trust him completely.", "o": ["totally", "fairly a bit"], "a": 0, "ex": ""}, {"q": "The opposite of \"considerate\" is _____.", "o": ["inconsiderate", "disconsiderate"], "a": 0, "ex": ""}];
LESSONS["1B"].convo1=[{"q": "Who's someone you really admire, and why?", "sample": "Honestly, I'd have to say my older sister. She's incredibly hard-working — like, she'll stay up late finishing something just to make sure it's done right. And she's extremely reliable too, which I really admire; if she says she'll do something, she just does it, no excuses. She can be pretty disorganized sometimes, honestly — she forgets stuff all the time, loses her keys, that kind of thing — but she's completely honest, so you always know exactly where you stand with her. And even though she's really talented at her job and could easily brag about it, she's not arrogant at all. I think that combination is pretty rare, actually.", "glossary": {}, "hl": ["incredibly", "extremely", "reliable", "pretty", "disorganized", "completely", "honest", "arrogant", "talented"]}];
LESSONS["1B"].convo2=[{"q": "Tell me about a friend or coworker who's really easy to get along with.", "sample": "Yeah, so, my coworker Sam is probably the first person who comes to mind. He's fairly easygoing — like, nothing really seems to stress him out, even when deadlines are tight. He's very down-to-earth too, so whenever I bring him a problem, he doesn't overreact, he just gives me really practical advice and helps me figure it out. He's not pushy or competitive at all either, which makes him easy to work with. And honestly, he's totally reliable — if he says he'll help with something, he actually does it, every time. We just get along really well, and I think a lot of that comes from him being so easygoing.", "glossary": {}, "hl": ["fairly", "easygoing", "down-to-earth", "competitive", "totally", "reliable"]}];
LESSONS["1B"].sessions=[{"id": "cb1", "stage": "Coursebook", "icon": "💬", "title": "Who Do You Admire?", "fa": "متن: چه کسی را تحسین می‌کنید؟", "parts": [{"t": "context", "label": "Context", "title": "Who Is Someone You Really Admire?", "lines": [{"sp": "Jessica Davis", "text": "My English teacher. She's incredibly talented and creative. And she has a great sense of humor. She's pretty disorganized, though. She forgets something almost every class, but her classes are absolutely wonderful!"}, {"sp": "Mike Kowalski", "text": "I really admire a guy in my karate class. He's extremely competitive, but when he wins, he's not arrogant like some of the other guys. He's not very outgoing, so some people think he's unfriendly, but I think he's basically just shy."}, {"sp": "Bryan Yuen", "text": "I think my dad's a pretty cool guy. We get along really well. He's fairly easygoing and laid-back. And he's very practical and down-to-earth, so he always gives me good advice. Also, he's completely honest with me. I can trust what he says."}, {"sp": "Emilia Perez", "text": "My friend Luisa. She's so helpful and generous. I mean, she's always doing things for other people. She's not selfish at all. And she's totally reliable. If she says she'll help you with something, she does. You can always count on her."}]}]}, {"id": "cb2", "stage": "Coursebook", "icon": "⭕", "title": "Pre-test", "fa": "پیش‌آزمون", "parts": [{"t": "selfcheck", "key": "pretest", "label": "Pre-test"}]}, {"id": "cb3", "stage": "Coursebook", "icon": "📝", "title": "Degree Adverbs", "fa": "آموزش: قیدهای شدت و پیشوندها", "parts": [{"t": "teach", "pts": [0, 1, 2, 3, 4]}]}, {"id": "cb4", "stage": "Coursebook", "icon": "✅", "title": "Exercise", "fa": "تمرین کتاب", "parts": [{"t": "bookExercise", "key": "bookExA", "label": "Exercise"}]}, {"id": "cb5", "stage": "Coursebook", "icon": "🔁", "title": "Building Vocabulary", "fa": "تقویت واژگان", "parts": [{"t": "bookExercise", "key": "buildingVocab", "label": "Building Vocabulary"}]}, {"id": "ex1", "stage": "Extra", "icon": "📚", "title": "Vocabulary 1", "fa": "لغات ۱", "parts": [{"t": "vocab", "from": 0, "to": 10}, {"t": "matching", "sets": [1, 2]}]}, {"id": "ex2", "stage": "Extra", "icon": "📚", "title": "Vocabulary 2", "fa": "لغات ۲", "parts": [{"t": "vocab", "from": 10, "to": 20}, {"t": "matching", "sets": [3, 4]}, {"t": "gap"}]}, {"id": "ex3", "stage": "Extra", "icon": "🎯", "title": "Grammar Quiz 1", "fa": "آزمون گرامر ۱", "parts": [{"t": "quizset", "key": "extraQuiz1", "label": "Grammar Quiz 1"}]}, {"id": "ex4", "stage": "Extra", "icon": "🎯", "title": "Grammar Quiz 2", "fa": "آزمون گرامر ۲", "parts": [{"t": "quizset", "key": "extraQuiz2", "label": "Grammar Quiz 2"}]}, {"id": "ex5", "stage": "Extra", "icon": "🗣️", "title": "Conversation Practice 1", "fa": "تمرین مکالمه ۱", "parts": [{"t": "convo", "key": "convo1"}]}, {"id": "ex6", "stage": "Extra", "icon": "🗣️", "title": "Conversation Practice 2", "fa": "تمرین مکالمه ۲", "parts": [{"t": "convo", "key": "convo2"}]}, {"id": "ex7", "stage": "Extra", "icon": "📖", "title": "Article 1", "fa": "مقاله ۱", "parts": [{"t": "reading", "text": 0}]}, {"id": "ex8", "stage": "Extra", "icon": "📖", "title": "Article 2", "fa": "مقاله ۲", "parts": [{"t": "reading", "text": 1}]}, {"id": "ex9", "stage": "Extra", "icon": "✍️", "title": "Writing", "fa": "نوشتن", "parts": [{"t": "writing"}]}];

