LESSONS["1C"].vocab=[["drive someone crazy", "idiom", "دیوانه کردن / کلافه کردن کسی", "His constant pen-clicking during meetings is starting to drive me crazy."], ["bring up an issue", "chunk", "مطرح کردن یک موضوع یا مشکل", "It is usually best to bring up an issue privately rather than in front of the whole team."], ["clear the air", "idiom", "برطرف کردن سوءتفاهم‌ها و کدورت‌ها", "We had an open discussion yesterday to clear the air after our disagreement."], ["a minor irritation", "chunk", "یک ناراحتی یا آزار کوچک", "Leaving cabinet doors open is a minor irritation, but doing it daily gets annoying."], ["diplomatic approach", "collocation", "رویکرد دیپلماتیک و با سیاست", "Taking a diplomatic approach helps resolve office conflicts without hurting feelings."], ["accumulate over time", "chunk", "به مرور زمان انباشته شدن", "Unaddressed habit irritations tend to accumulate over time into major arguments."], ["cognitive reframing", "collocation", "بازسازی شناختی (تغییر زاویه دید)", "Practicing cognitive reframing allows you to view a colleague's quirks with more patience."], ["stand up for yourself", "chunk", "از حق خود دفاع کردن", "You need to stand up for yourself politely when a coworker takes credit for your work."], ["disrupt team productivity", "chunk", "اختلال در بازدهی تیم", "Loud personal phone calls in an open office disrupt team productivity significantly."], ["tolerable behavior", "collocation", "رفتار قابل تحمل", "We need to distinguish between intolerable actions and simple, tolerable behavior."], ["workplace etiquette", "collocation", "آداب و قوانین رفتار در محیط کار", "Following basic workplace etiquette creates a comfortable environment for everyone."], ["take something personally", "idiom", "چیزی را به خود گرفتن / شخصی تلقی کردن", "Try not to take her sharp tone personally; she is under a lot of deadline pressure."], ["address a colleague", "collocation", "مخاطب قرار دادن / صحبت کردن با همکار", "It is important to address a colleague respectfully when pointing out a mistake."], ["smooth things over", "idiom", "آرام کردن اوضاع / حل و فصل کردن ارام مشکلات", "He bought coffee for the team to smooth things over after arriving late to the presentation."], ["mutual understanding", "collocation", "درک متقابل", "Building mutual understanding makes it easier to handle personal differences at work."], ["lose your cool", "idiom", "از کوره در رفتن / کنترل خود را از دست دادن", "Even when a coworker interrupts you repeatedly, try not to lose your cool."], ["set clear boundaries", "chunk", "تعیین مرزهای مشخص", "Setting clear boundaries early prevents colleagues from overloading you with extra tasks."], ["a touchy subject", "idiom", "موضوع حساس و دردسرساز", "Punctuality turned out to be a touchy subject during our performance review."], ["foster a positive environment", "chunk", "ترویج/ایجاد یک فضای مثبت", "Managers who listen to complaints actively foster a positive environment."], ["bite your tongue", "idiom", "جلوی زبان خود را گرفتن / سکوت کردن", "I had to bite my tongue during the meeting to avoid making an angry comment."]];
LESSONS["1C"].texts=[{"title": "Text 1: Handling Daily Workplace Irritations Diplomatically", "topic": "Handling Daily Workplace Irritations Diplomatically", "text": "In any modern office or shared space, people with different backgrounds, habits, and communication styles must work together every day. While working with different people brings many benefits to a company, sharing a physical or virtual work environment often highlights differences in daily habits. Over time, small habits that seem harmless to one person can become a major source of annoyance for another. Understanding how daily workplace habits affect team results, and learning how to address annoying actions politely, is essential for keeping professional peace and personal happiness.\n\nWorkplace habits that break concentration and slow down daily work are surprisingly common across many companies. For example, colleagues who frequently answer phone calls on speakerphone, leave dirty dishes in the kitchen area, or talk loudly in open offices can create an environment where focus becomes nearly impossible. Similarly, arriving late for group meetings or failing to reply to urgent emails forces team members to change their plans needlessly. When workers face continuous disruptions, their stress levels increase and their overall results drop. What begins as a minor habit annoyance can quickly build up into deep anger if people choose to ignore it for too long.\n\nWhen dealing with a difficult colleague, many workers make the mistake of suffering in silence or reacting with sudden anger. Neither approach solves the main problem. A far more effective strategy involves addressing the behavior politely before emotions become too strong. Choosing the right time and private place for a conversation is critical. Rather than complaining about a colleague in front of other workers, ask for a quiet private discussion. Speak calmly and focus on the specific action itself rather than attacking the person's character. For instance, explaining how loud calls make it hard for you to focus on important reports is much more helpful than calling a colleague rude.\n\nIn addition to direct communication, changing how you think about a situation offers a powerful mental tool for handling actions you cannot fully control. Instead of assuming a colleague's annoying habit is done on purpose, remind yourself that people rarely try to annoy others deliberately. They may simply be unaware of their habit or dealing with personal stress at home. Thinking about the situation differently helps reduce emotional stress, allowing you to react with patience rather than anger.\n\nFinally, self-awareness plays a vital role in keeping good relationships with team members. It is easy to notice irritating habits in others while remaining completely unaware of our own. Taking time to examine your own daily habits in the office can reveal actions that might be annoying to your peers. Asking for honest feedback from trusted colleagues shows maturity and a commitment to good teamwork. Ultimately, creating a peaceful workplace requires effort from everyone. By practicing open communication, emotional control, and mutual respect, workers can solve habit conflicts successfully and build strong working relationships over time. Strong teamwork always begins with clear communication and mutual respect.", "glossary": {}, "hl": [], "gist": {"q": "What is the primary purpose of the text?", "o": ["To explain why employees should report annoying colleagues to human resources immediately.", "To offer practical strategies for managing workplace habit conflicts through communication and reframing.", "To argue that working from home is superior to working in open shared office spaces.", "To list the most common technical skills required for professional success in modern companies."], "a": 1}, "detailed": [{"q": "What mistake do many workers make when facing a frustrating colleague?", "o": ["They write formal complaints to executive directors.", "They suffer in silence or react with sudden anger.", "They change their working hours without telling anyone.", "They ask for an immediate transfer to a different department."], "a": 1}, {"q": "How does the author suggest framing a discussion about an annoying behavior?", "o": ["Focus on the person's personality traits and past failures.", "Discuss the problem publicly during a team meeting.", "Focus objectively on the specific action and its impact on your work.", "Insist that the colleague apologize before listening to their side."], "a": 2}, {"q": "What benefit does changing how you view a colleague's action provide?", "o": ["It forces the other person to change their behavior automatically.", "It completely eliminates the need for professional teamwork.", "It reduces emotional stress by helping you react with patience.", "It proves to your manager that you are always right."], "a": 2}]}, {"title": "Text 2: Why Small Irritations Accumulate into Major Conflicts", "topic": "Why Small Irritations Accumulate into Major Conflicts", "text": "Human beings are creatures of habit, relying on familiar daily routines to navigate their personal and professional lives. However, when these individual habits clash in shared spaces like offices, schools, or homes, friction is almost inevitable. Small irritations, such as leaving cabinet doors open, constantly interrupting during team discussions, or misplacing shared tools, may seem minor by themselves. Yet, when repeated daily over weeks or months, these small annoyances build up into serious personal conflicts. Understanding why small habit irritations cause such strong reactions is the first step toward managing them effectively and keeping healthy relationships.\n\nThe psychological reason small irritations build up so quickly relates to how the human mind handles stress and personal boundaries. When someone repeatedly does something annoying, the affected person begins to expect the problem before it even happens. This constant state of waiting for a problem creates continuous mild stress, making the person increasingly sensitive to the action. Over time, what was originally a minor distraction feels like a deliberate sign of disrespect. Consequently, a sudden argument may break out over a very small event, surprising the person who caused it because they failed to see how much tension had been growing over time.\n\nTo prevent small irritations from damaging professional or personal relationships, individuals must learn how to address annoying behaviors politely. Timely, honest communication is essential. Waiting until you are completely overwhelmed usually leads to angry statements that make the other person defensive. Instead, bring up the issue early using calm and neutral language. Focus on finding practical solutions rather than demanding complete perfection. For example, if a teammate's messy file system slows down shared projects, suggest a simple, organized system that helps both of you, rather than simply complaining about their messy habits.\n\nWhen dealing with habits that cannot easily be changed, changing your mental focus serves as a very useful strategy. This does not mean ignoring real problems, but rather adjusting your perspective to reduce personal stress. By accepting that everyone has unique habits and occasional annoying traits, you can lower your expectations of complete perfection from others. Reminding yourself of a colleague's positive work helps keep minor habit annoyances in proper balance, preventing brief moments of frustration from ruining your working relationship.\n\nFurthermore, developing strong team relationships requires honest self-awareness. People often judge others by their actions while judging themselves by their good intentions. You might excuse your own habit of arriving late to a meeting because you were busy, yet feel angry when a colleague does the exact same thing. Developing understanding allows you to recognize that your habits might be equally annoying to co-workers or family members. When teams build a culture of mutual understanding and forgiveness, individuals feel comfortable discussing problems openly without fear of harsh judgment. Through active listening, polite discussion, and personal flexibility, people can transform habit conflicts into opportunities for stronger teamwork and personal growth. Taking steps to respect each other's habits leads to long-term success. Learning to accept minor differences helps everyone maintain peace and productiveness.", "glossary": {}, "hl": [], "gist": {"q": "What is the main idea of the article?", "o": ["Minor habit irritations build up over time due to stress expectations, but can be managed through early communication and self-awareness.", "Personal conflicts in offices are impossible to avoid and usually require changing jobs.", "Most employees disrupt shared spaces on purpose to irritate their colleagues.", "Perfection is required from every team member to achieve workplace harmony."], "a": 0}, "detailed": [{"q": "According to the text, why do small irritations cause explosive arguments eventually?", "o": ["Because people forget what started the original argument.", "Because constant anticipation of the disruption creates continuous stress over time.", "Because managers encourage employees to hold back their feelings.", "Because small habits always cost companies money."], "a": 1}, {"q": "What is recommended when bringing up a habit issue with a colleague?", "o": ["Wait until you are furious so they understand the severity.", "Bring it up early using calm, neutral language focused on practical solutions.", "Send an anonymous complaint to executive leadership.", "Demand that the person change their entire personality immediately."], "a": 1}, {"q": "How does judging ourselves versus judging others create misunderstandings?", "o": ["We judge others by their actions while judging ourselves by our good intentions.", "We always judge ourselves much more harshly than we judge others.", "We ignore our own work achievements while praising coworkers.", "We assume everyone else has perfect time-management skills."], "a": 0}]}];
LESSONS["1C"].writing={"prompts": [{"title": "Prompt 1", "text": "Describe a minor habit or behavior of a colleague or family member that you used to find frustrating. Explain how you brought up the issue or changed your perspective to resolve the situation, and what you learned from the experience."}, {"title": "Prompt 2", "text": "Write a response to a colleague who has approached you about a personal habit that is disrupting their work (e.g., talking loudly on calls or leaving items in shared spaces). Practice acknowledging their feelings politely, explaining your side diplomatically, and proposing a practical compromise."}]};
LESSONS["1C"].grammar={points:[{"label": "استراتژی ۱", "title": "Always + continuous — describing habits", "html": "<h3>قاعده</h3>\n<p>برای صحبت درباره‌ی عادت‌های تکراری یک شخص (که معمولاً کمی ما را آزرده می‌کند)، از ساختار <b>am/is/are always + فعل‌ing</b> استفاده می‌کنیم.</p>\n<div class=\"ex\">He's <span class=\"hl\">always smiling</span>. · He's <span class=\"hl\">always disturbing</span> people.</div>\n<div class=\"note\">این ساختار معمولاً نشان‌دهنده‌ی کمی آزردگی یا تعجب از یک عادت است، نه فقط توصیف خنثی.</div>"},{"label": "استراتژی ۲", "title": "At least — نکته‌ی مثبت در یک موقعیت", "html": "<h3>قاعده</h3>\n<p>از عبارت <b>at least</b> برای اشاره به نکته‌ی مثبت یک موقعیت منفی استفاده می‌کنیم.</p>\n<div class=\"ex\">\"He's always standing around and talking.\" → \"Well, <span class=\"hl\">at least</span> he's pleasant.\"</div>\n<div class=\"note\">at least یکی از ۵۰۰ عبارت پرکاربرد در انگلیسی محاوره‌ای است.</div>"}],bookExC4:[{"q": "Everyone in my family loves music. We sing together. → We ____ together.", "o": ["are always singing", "always sing"], "a": 0, "ex": "عادتی که کمی زیاده‌روی دارد → always + ing."}, {"q": "My brother is really generous with his time. He fixes my computer. → He ____ my computer.", "o": ["is always fixing", "always fixes"], "a": 0, "ex": ""}, {"q": "My father is a workaholic. He comes home late. → He ____ home late.", "o": ["is always coming", "always comes"], "a": 0, "ex": ""}, {"q": "My college roommate was really funny. She told jokes. → She ____ jokes.", "o": ["was always telling", "always told"], "a": 0, "ex": ""}, {"q": "A friend of mine complains she's broke, but she buys expensive clothes. → She ____ expensive clothes.", "o": ["is always buying", "always buys"], "a": 0, "ex": ""}, {"q": "One of my friends is totally unreliable. He cancels plans at the last minute. → He ____ plans at the last minute.", "o": ["is always canceling", "always cancels"], "a": 0, "ex": ""}],bookExC6:[{"q": "My girlfriend's always running behind, but she calls to say she'll be late. → Well, ____ she calls.", "o": ["at least", "at last"], "a": 0, "ex": ""}, {"q": "My best friend is always borrowing my clothes, but she returns them in good condition. → Well, ____ she returns them nicely.", "o": ["at least", "at all"], "a": 0, "ex": ""}, {"q": "One of my classmates talks about himself a lot, but his stories are always interesting. → Well, ____ his stories are interesting.", "o": ["at least", "at once"], "a": 0, "ex": ""}, {"q": "My roommate sleeps all the time, but she doesn't snore. → Well, ____ she doesn't snore!", "o": ["at least", "at all"], "a": 0, "ex": ""}, {"q": "My parents and I see things differently, but we don't have big fights. → Well, ____ we don't fight.", "o": ["at least", "at last"], "a": 0, "ex": ""}, {"q": "My boyfriend is always checking his messages, even at the movies! → At least he doesn't _____ it during the movie.", "o": ["answer", "lose"], "a": 0, "ex": "جواب نمی‌دهد به گوشی وسط فیلم."}, {"q": "My girlfriend is always telling jokes. → Well, at least she has a good sense of _____.", "o": ["humor", "time"], "a": 0, "ex": "have a great sense of humor."}, {"q": "I'm always losing pens and things. → Yeah, but at least you don't lose anything really _____.", "o": ["valuable", "cheap"], "a": 0, "ex": ""}, {"q": "My sister is always asking me for money. → Well, at least she asks _____.", "o": ["politely", "rudely"], "a": 0, "ex": "مکالمه می‌گوید she asks politely."}]};
LESSONS["1C"].sessions=[{"id": "cs1", "stage": "Coursebook", "icon": "💬", "title": "Conversation", "fa": "متن کامل مکالمه", "parts": [{"t": "context", "label": "Context", "title": "Max and Ellie talk about a co-worker", "lines": [{"sp": "Max", "text": "Hey, how are you getting along with your new co-worker? He seems extremely friendly. He's always smiling."}, {"sp": "Ellie", "text": "You mean Jim? Well, yeah, he is, but he never does any work. He's always disturbing people. It drives me crazy. You know, he's always standing around and talking."}, {"sp": "Max", "text": "Well, at least he's pleasant."}, {"sp": "Ellie", "text": "Yeah. And he's not always criticizing people like that last guy."}, {"sp": "Max", "text": "Yeah. He was pretty bad. He was always talking about people behind their backs."}, {"sp": "Ellie", "text": "I mean, at least Jim's not like that. But like, he's always wasting time."}, {"sp": "Max", "text": "You mean like we're doing right now?"}]}]}, {"id": "cs2", "stage": "Coursebook", "icon": "📝", "title": "Always + -ing", "fa": "توضیح: همیشه + ing", "parts": [{"t": "teach", "pts": [0]}]}, {"id": "cs3", "stage": "Coursebook", "icon": "👆", "title": "Find the pattern", "fa": "الگو را پیدا کنید", "parts": [{"t": "tapfind", "prompt": "Tap every line where Max or Ellie use always + -ing to describe a habit.", "lines": [{"sp": "Max", "text": "Hey, how are you getting along with your new co-worker? He seems extremely friendly. He's always smiling."}, {"sp": "Ellie", "text": "You mean Jim? Well, yeah, he is, but he never does any work. He's always disturbing people. It drives me crazy. You know, he's always standing around and talking."}, {"sp": "Max", "text": "Well, at least he's pleasant."}, {"sp": "Ellie", "text": "Yeah. And he's not always criticizing people like that last guy."}, {"sp": "Max", "text": "Yeah. He was pretty bad. He was always talking about people behind their backs."}, {"sp": "Ellie", "text": "I mean, at least Jim's not like that. But like, he's always wasting time."}, {"sp": "Max", "text": "You mean like we're doing right now?"}]}]}, {"id": "cs4", "stage": "Coursebook", "icon": "✅", "title": "Exercise", "fa": "تمرین D کتاب", "parts": [{"t": "bookExercise", "key": "bookExC4", "label": "Exercise"}]}, {"id": "cs5", "stage": "Coursebook", "icon": "➕", "title": "At Least", "fa": "توضیح: حداقل", "parts": [{"t": "teach", "pts": [1]}]}, {"id": "cs6", "stage": "Coursebook", "icon": "✅", "title": "More Practice", "fa": "تمرین «حداقل»", "parts": [{"t": "bookExercise", "key": "bookExC6", "label": "Exercise"}]}, {"id": "ex1", "stage": "Extra", "icon": "📚", "title": "Vocabulary 1", "fa": "لغات ۱", "parts": [{"t": "vocab", "from": 0, "to": 10}, {"t": "matching", "sets": [1, 2]}]}, {"id": "ex2", "stage": "Extra", "icon": "📚", "title": "Vocabulary 2", "fa": "لغات ۲", "parts": [{"t": "vocab", "from": 10, "to": 20}, {"t": "matching", "sets": [3, 4]}, {"t": "gap"}]}, {"id": "ex3", "stage": "Extra", "icon": "📖", "title": "Article 1", "fa": "مقاله ۱", "parts": [{"t": "reading", "text": 0}]}, {"id": "ex4", "stage": "Extra", "icon": "📖", "title": "Article 2", "fa": "مقاله ۲", "parts": [{"t": "reading", "text": 1}]}, {"id": "ex5", "stage": "Extra", "icon": "✍️", "title": "Writing", "fa": "نوشتن", "parts": [{"t": "writing"}]}];

/* ---- Unit 1 Lesson D rebuild ---- */
LESSONS["1D"].vocab=[["construct a profile", "collocation", "ساختن یک پروفایل/رزومه", "Learning to construct a profile clearly helps you attract potential employers."], ["digital footprint", "collocation", "ردپای دیجیتال", "Your digital footprint includes everything you post or share on social media."], ["maintain an authentic image", "chunk", "حفظ یک تصویر واقعی و اصیل", "It is important to maintain an authentic image while keeping your profile professional."], ["stand out from the crowd", "idiom", "متمایز بودن از دیگران", "Highlighting unique achievements helps your resume stand out from the crowd."], ["career gap", "collocation", "وقفه کاری", "Explaining a career gap with honesty shows confidence and personal maturity."], ["overshare personal details", "chunk", "زیاده‌روی در اشتراک‌گذاری اطلاعات شخصی", "Avoid the temptation to overshare personal details on professional networking sites."], ["unconventional path", "collocation", "مسیر غیرمعمول/غیرسنتی", "Following an unconventional path can bring valuable life experiences to your work."], ["convey reliability", "chunk", "نشان دادن قابل اعتماد بودن", "Using clear, direct language in your biography helps convey reliability."], ["professional bio", "collocation", "بیوگرافی حرفه‌ای", "A short professional bio summarizes your key achievements and current goals."], ["strike a balance", "idiom", "ایجاد تعادل", "It can be hard to strike a balance between being modest and showing your strengths."], ["networking platform", "collocation", "پلتفرم شبکه‌سازی کاری", "LinkedIn is a popular networking platform used by job seekers around the world."], ["present yourself in a positive light", "chunk", "نشان دادن خود به شکل مثبت", "Always present yourself in a positive light without exaggerating your skills."], ["public persona", "collocation", "شخصیت عمومی", "A professional's public persona should reflect their core values and work ethics."], ["leave a good impression", "chunk", "به جا گذاشتن اثر مثبت", "A well-designed profile leaves a good impression on recruiters within seconds."], ["tailor your summary", "chunk", "متناسب‌سازی خلاصه رزومه", "Be sure to tailor your summary for each job application you submit."], ["keep it relevant", "chunk", "مرتبط نگه داشتن مطالب", "When writing your bio, keep it relevant to the industry you want to enter."], ["hide behind a filter", "idiom", "پنهان شدن پشت نقاب/فیلتر", "True professionals do not hide behind a filter; they let their work speak for itself."], ["highlight key achievements", "chunk", "برجسته‌سازی دستاوردهای اصلی", "Your profile should highlight key achievements using clear, measurable examples."], ["protect your reputation", "chunk", "محافظت از اعتبار خود", "Thinking carefully before posting comments online helps protect your reputation."], ["unintentional mistake", "collocation", "اشتباه غیرعمدی", "An unintentional mistake on social media can sometimes affect your career prospects."]];
LESSONS["1D"].texts=[{"title": "Text 1: Constructing an Authentic Professional Profile", "topic": "Constructing an Authentic Professional Profile", "text": "Building a strong personal profile has become essential for career success in the modern digital world. Whether you are applying for a new job, networking at professional conferences, or creating an online biography, presenting yourself clearly is critical. A well-written profile introduces your skills, experiences, and personal values in a clear, interesting way. However, many working professionals struggle to find the right balance between being completely honest and presenting a polished professional image. Learning how to construct an authentic biography helps you connect with employers while protecting your professional reputation. Taking time to carefully design your personal narrative is one of the most effective investments you can make for your long-term professional development.\n\nOne of the first challenges in writing a personal profile is defining your target audience and core message. A professional biography should highlight your key achievements and practical skills without sounding overly boastful. Focus on specific results and roles rather than using vague adjectives. For example, describing how you managed team projects, improved daily sales, or solved complex client problems provides concrete proof of your abilities. Furthermore, choosing a clear and respectful tone of voice helps convey confidence and reliability. Keeping your sentences direct, engaging, and well-organized allows busy hiring managers and professional contacts to understand your complete professional background quickly and easily.\n\nAnother important aspect of modern profiles is managing your digital footprint on social networking sites. Today, many employers search for job candidates online before scheduling formal job interviews. Oversharing personal struggles, strong political opinions, or negative comments about previous employers on public platforms can harm your professional image severely. While being genuine is valuable, maintaining appropriate boundaries between your private life and public profile is essential. Keeping your public posts respectful, constructive, and professional ensures that your digital footprint reflects positively on your personal character and professional work ethic across every digital platform.\n\nFinally, many individuals worry about how to present career gaps or unconventional work paths in their written biographies. Rather than trying to hide periods of unemployment, career changes, or personal sabbaticals, frame these experiences as valuable opportunities for personal growth. Highlight any freelance projects, voluntary work, or continuous online learning you completed during those times. Taking time to learn new skills or care for family members demonstrates resilience, maturity, and adaptability. When you explain your career path with complete honesty and self-assurance, potential employers appreciate your self-awareness and practical perspective.\n\nIn conclusion, your personal profile is a dynamic document that should evolve as you progress in your professional journey. By reviewing your biographical summary annually, you ensure that your public image reflects your most current skills and aspirations. Seeking feedback from trusted mentors can also provide valuable insight into how others perceive your professional profile. Taking proactive steps to refine your summary demonstrates dedication to self-improvement and long-term career growth. Investing time into building a clear digital identity will consistently yield positive professional results.", "glossary": {}, "hl": [], "gist": {"q": "What is the primary purpose of the article?", "o": ["To explain how to create a resume specifically for sales management positions.", "To offer advice on writing an authentic professional biography and managing digital presence.", "To argue that social media platforms should be banned for professional networking.", "To convince job candidates to conceal all employment gaps on their resumes."], "a": 1}, "detailed": [{"q": "What should job applicants focus on when describing their work experience?", "o": ["Vague adjectives and general statements about their personality.", "Specific results, roles, and concrete proof of abilities.", "Detailed complaints about previous companies they worked for.", "Long lists of personal hobbies and weekend activities."], "a": 1}, {"q": "Why is it important to manage your digital footprint?", "o": ["Employers often research candidates online before scheduling interviews.", "Social media accounts automatically delete unmaintained profiles.", "Having a digital profile eliminates the need for formal job interviews.", "It is required by international labor laws in every country."], "a": 0}, {"q": "How does the author suggest handling career gaps in a biography?", "o": ["Hide them entirely by altering employment dates.", "Blame former employers for ending your contract.", "Frame them as opportunities for growth, highlighting freelance work or learning.", "Ignore them and hope employers do not notice."], "a": 2}]}, {"title": "Text 2: Navigating Digital Presence and Career Branding", "topic": "Navigating Digital Presence and Career Branding", "text": "In today's interconnected global economy, an individual's digital presence often serves as their first handshake with potential colleagues and employers. With the rapid expansion of professional networking sites, personal branding has evolved from an optional activity into an absolute professional necessity. However, crafting an effective digital persona requires careful navigation of personal privacy, communication tone, and authentic presentation. Understanding how your online actions impact your real-world reputation enables you to build a personal career brand that opens new professional doors while maintaining your integrity and values.\n\nA major concern for professionals active online is the subtle risk of oversharing personal details. Many workers feel constant pressure to post content continuously on networking platforms to remain visible to recruiters and industry peers. Unfortunately, sharing personal frustration, internal company debates, or overly emotional opinions can quickly undermine your hard-earned professional credibility. While online audiences value authenticity, confusing personal emotional expressions with professional openness can backfire badly. Maintaining clear boundaries between personal social accounts and professional public profiles allows you to preserve personal privacy while demonstrating sound judgment to potential clients, recruiters, and executive leadership.\n\nAnother crucial factor in personal branding is how you present unconventional career choices and non-traditional paths. Modern career trajectories are rarely linear or predictable. Many successful individuals transition between completely different industries, take extended sabbaticals for higher education, or temporarily step back to manage family responsibilities. When writing an online profile, framing these transitions as deliberate, positive steps toward personal development creates a compelling story. Demonstrating how diverse life experiences have equipped you with transferable skills—such as adaptability, problem-solving, emotional maturity, and cross-cultural communication—transforms a potentially disjointed background into a unique professional strength that sets you apart.\n\nFinally, long-term brand building relies heavily on maintaining absolute consistency across all digital platforms. Ensuring that your written biography, listed skills, employment history, and public posts align properly creates a coherent image that inspires trust among industry peers. Regularly updating your online profile with recent accomplishments, major project completions, or new professional certifications shows ongoing commitment and active engagement in your field.\n\nIn summary, managing your digital footprint requires ongoing attention and strategic thinking in today's fast-paced digital world. By periodically reviewing your privacy settings and evaluating the tone of your posts, you can protect your professional reputation effectively. Engaging thoughtfully with industry discussions and sharing informative content establishes you as a knowledgeable and reliable professional in your field. Building a trustworthy digital brand takes patience, but the long-term career benefits are substantial. Continuous learning and intentional networking will always support your professional journey across all industries.", "glossary": {}, "hl": [], "gist": {"q": "What is the main theme of the article?", "o": ["The importance of creating a consistent, well-bounded, and authentic digital presence for career growth.", "Why traditional linear career paths are the only way to achieve executive success.", "How to use personal social media accounts to complain about company policies safely.", "Why online networking platforms are losing popularity among modern employers."], "a": 0}, "detailed": [{"q": "What risk is associated with oversharing on professional networking platforms?", "o": ["It reduces the storage space on your digital devices.", "It can undermine professional credibility and demonstrate poor judgment.", "It forces employers to increase your starting salary.", "It automatically changes your profile privacy settings to public."], "a": 1}, {"q": "How can transferable skills from unconventional paths be presented in a profile?", "o": ["By presenting diverse experiences as evidence of adaptability and problem-solving.", "By pretending the unconventional experiences never occurred.", "By claiming that non-traditional paths are mandatory for all workers.", "By listing every daily task performed during gap years in detail."], "a": 0}, {"q": "What helps build long-term trust in personal branding?", "o": ["Changing your professional title every few weeks.", "Maintaining consistency across all public profiles and updating accomplishments regularly.", "Using artificial intelligence to write every single post.", "Keeping all professional achievements secret until job interviews."], "a": 1}]}];
LESSONS["1D"].mainReading=[{"title": "Student Profiles", "topic": "Mariana, Mateo, Katya, Ahmed", "text": "MARIANA BARELLI MATOS\nWhat's your major? Fashion design. My dream is to create incredibly beautiful clothes for women all over the world.\nWhere are you based? In Milan. I was born and raised in Sao Paulo, Brazil, but my mother's Italian. She felt very strongly that I should experience her culture.\nWhy did you choose your major? I inherited my mother's love of fashion. She's very style-conscious and has impeccable taste in clothes.\nWhat skills do you have? I speak Portuguese and Italian fluently and have some knowledge of Mandarin.\nWhat do you do in your free time? I love the outdoors, and I'm fairly adventurous. During the summers I volunteer at a camp for disadvantaged children. It's extremely rewarding.\n\nMATEO REYES\nWhere are you from? I was born and raised in Veracruz, Mexico.\nWhat do your friends say about you? They say that I'm extremely laid-back and even-tempered. And that I'm too humble about my talents.\nWhat are your future plans? I have so many. Right now I'm working for a small production company called Film Fast. My major was film studies, and my goal is to tell real-life stories creatively through television and film.\nWhat do you do in your free time? I like to cook, and I'm always trying out new recipes, especially for desserts.\nWhat's something people don't know about you? When I was 12, I was on a reality TV show for young chefs. I didn't win, but at least I tried.\n\nKATYA AKILOVA\nWhere are you based? In Moscow, Russia, though I'm from St. Petersburg, originally.\nWhat do your friends say about you? That I'm very down-to-earth, hard-working, and incredibly organized, and that I'm always setting goals for myself.\nWhat's your worst habit? I'm always doing something. I find it hard to relax.\nWhat are your future plans? As a science major, I'm considering a career as an environmentalist because I feel strongly about protecting the environment.\nWhat skills do you have? I'm an accomplished accordion player. I started playing at the age of eight. I'd love to play professionally with an orchestra.\n\nAHMED ABD EL-SALAM\nWhat's your job? I'm an engineer. I work for a big company called Syntix.\nWhy did you choose to study online? You get to \"meet\" an incredibly diverse range of students, and the teachers are extremely supportive. I can be pretty shy and introverted and studying online feels safe somehow.\nDo you have a secret talent? I play guitar in a band called All Kinds. We play all kinds of music. I feel like a totally different person in the band - outgoing and not shy at all.\nWhat are your tips for new students? Take your studies seriously. Make the most of your opportunities to practice English with other students.", "glossary": {}, "hl": ["style-conscious", "laid-back", "humble", "organized", "considering", "diverse", "introverted", "outgoing"], "gist": {"q": "What is this reading mainly about?", "o": ["Four students describing their background, studies, and personality", "A comparison of fashion schools", "An interview about reality TV shows"], "a": 0, "ex": ""}, "detailed": [{"q": "Who has been on a reality TV show?", "o": ["Mateo", "Mariana", "Katya", "Ahmed"], "a": 1, "ex": "در متن مطئو گفته وقتی ۱۲ سالش بود در یک برنامه تلویزیونی آشپزی بود."}, {"q": "Who plays a musical instrument?", "o": ["Katya", "Mariana", "Mateo", "Ahmed's friend"], "a": 0, "ex": "کاتیا آکاردئون می‌نوازد."}, {"q": "Which student already has a full-time job?", "o": ["Ahmed", "Mariana", "Katya", "Mateo"], "a": 0, "ex": "احمد مهندس است و برای یک شرکت کار می‌کند."}, {"q": "Which two students are described as hard-working or serious about their goals?", "o": ["Katya and Mariana", "Mateo and Ahmed", "Only Mateo", "Only Ahmed"], "a": 0, "ex": "کاتیا و ماریانا هر دو در متن به‌عنوان افرادی هدفمند و پرتلاش توصیف شده‌اند."}, {"q": "Who plays guitar in a band?", "o": ["Ahmed", "Mateo", "Katya", "Mariana"], "a": 0, "ex": "احمد در گروه All Kinds گیتار می‌زند."}, {"q": "The word 'disadvantaged' in Mariana's profile describes children who are...", "o": ["poor / lacking opportunities", "very talented", "from Italy", "studying fashion"], "a": 0, "ex": "disadvantaged یعنی محروم یا کم‌برخوردار."}, {"q": "Katya says she is 'considering' a career as an environmentalist. This means she...", "o": ["is thinking about it, not decided yet", "has already started that job", "doesn't want that career", "studied it years ago"], "a": 0, "ex": "consider یعنی در نظر گرفتن، هنوز تصمیم قطعی نیست."}]}];
LESSONS["1D"].writing={"prompts": [{"title": "Prompt 1", "text": "Write a short professional biography (100–150 words) suitable for a networking profile. Include your current role or field of study, key skills, major accomplishments, and future career ambitions while keeping an authentic tone."}, {"title": "Prompt 2", "text": "Write an essay discussing whether employees should keep their personal values and political views separate from their professional public profiles. Explain your reasoning with clear examples."}]};
LESSONS["1D"].writingTask={"title": "Your profile", "text": "Write your own profile (100–150 words). Choose five questions from the reading (for example: where you're from, your major/job, a skill, a free-time habit, a secret talent), and include at least one thing other people don't know about you. Don't write your name — your teacher may read it aloud and let the class guess who wrote it."};
LESSONS["1D"].sessions=[{"id": "cb1", "stage": "Coursebook", "icon": "🔎", "title": "Scan first", "fa": "ابتدا مرور سریع کنید", "parts": [{"t": "scanpre", "src": "mainReading", "text": 0}]}, {"id": "cb2", "stage": "Coursebook", "icon": "📖", "title": "Reading", "fa": "متن کامل", "parts": [{"t": "fullread", "src": "mainReading", "text": 0}]}, {"id": "cb3", "stage": "Coursebook", "icon": "✅", "title": "Comprehension", "fa": "درک مطلب", "parts": [{"t": "comprehension", "src": "mainReading", "text": 0}]}, {"id": "cb4", "stage": "Coursebook", "icon": "📝", "title": "Sample", "fa": "نمونه‌ی نوشتاری", "parts": [{"t": "writingSample", "title": "About A: a student profile", "text": "About A Write a profile about yourself. Choose five questions from the student profiles, and include information that other people don't know about you. Don't write your name.\n\nFive things you don't know about me\n\n1. Where are you from?\nI was born and raised in Istanbul, Turkey, but I moved here at the age of 14.\n\n2. Do you have a secret talent?"}]}, {"id": "cb5", "stage": "Coursebook", "icon": "💡", "title": "Writing Tips", "fa": "نکات نوشتن", "parts": [{"t": "writingPoints", "title": "What to include", "html": "<h3>نکات نوشتن پروفایل</h3>\n<ul style=\"padding-right:18px;line-height:2\">\n<li>۵ سؤال از میان سؤالات پروفایل‌های دانشجویان را انتخاب کنید.</li>\n<li>حداقل یک نکته‌ی «کسی از آن خبر ندارد» درباره‌ی خودتان بنویسید.</li>\n<li>اسم خودتان را ننویسید — این یک بازی حدس‌زدن است.</li>\n<li>از عبارت‌هایی مثل <b>I was born and raised in...</b> و <b>I can be...</b> و <b>I'm an accomplished...</b> استفاده کنید.</li>\n</ul>"}]}, {"id": "cb6", "stage": "Coursebook", "icon": "✍️", "title": "Write your profile", "fa": "پروفایل خودتان را بنویسید", "parts": [{"t": "writing", "key": "taskOnly"}]}, {"id": "ex1", "stage": "Extra", "icon": "📚", "title": "Vocabulary 1", "fa": "لغات ۱", "parts": [{"t": "vocab", "from": 0, "to": 10}, {"t": "matching", "sets": [1, 2]}]}, {"id": "ex2", "stage": "Extra", "icon": "📚", "title": "Vocabulary 2", "fa": "لغات ۲", "parts": [{"t": "vocab", "from": 10, "to": 20}, {"t": "matching", "sets": [3, 4]}, {"t": "gap"}]}, {"id": "ex3", "stage": "Extra", "icon": "📖", "title": "Article 1", "fa": "مقاله ۱", "parts": [{"t": "reading", "text": 0}]}, {"id": "ex4", "stage": "Extra", "icon": "📖", "title": "Article 2", "fa": "مقاله ۲", "parts": [{"t": "reading", "text": 1}]}, {"id": "ex5", "stage": "Extra", "icon": "✍️", "title": "Writing", "fa": "نوشتن", "parts": [{"t": "writing"}]}];

